             ["ПК-X (SOM по сценариям)", *mk(S["SOM"]["ПК-X (SOM, сценарии)"]), "SOM", "Excel"],
             ["ПК, диапазоны К1–К5 (SOM)", *mk([pk["word_ranges"][k][1] for k in ("cautious", "base", "optimistic")]), "SOM", "Word"],
             ["ПЛ-X (достижимая выручка)", *mk(S["SOM"]["ПЛ-X (достижимая выручка)"]), "SOM", "Excel"],
             ["SW-X (SOM)", *mk(S["SOM"]["SW-X (SOM)"]), "SOM", "Excel"],
