    d.h(4, "2.10.3 Правила согласования результатов")
    ratio_td_bu = S["MARKET"]["СВ-X сверху вниз"][1] / S["MARKET"]["СВ-X снизу вверх"][1]
    ratio_cl_sw = S["MARKET"]["СВ-X снизу вверх"][1] / S["MARKET"]["SW-X (рынок)"][1]
    d.table("rules", "Применение правил согласования ИНСТР §11", ["Правило", "Проверка", "Результат"],
            [["«Сверху вниз» значительно больше «снизу вверх» — проверить коэффициенты", f"Базовый «сверху вниз» {n(S['MARKET']['СВ-X сверху вниз'][1], 0)}, «снизу вверх» {n(S['MARKET']['СВ-X снизу вверх'][1], 0)} BYN (в {n(ratio_td_bu, 1)} раза)", "Значительного превышения нет; различие — общая доля К2 × К4 (17,5 %) против сегментных (К4 студентов 8,75 %). Оптимистичный «сверху вниз» (2,8 млн) существенно выше — оценка верхнего предела"],
             ["Поисковый спрос высокий, платёжеспособность низкая — уточнить цену, сегмент, формат", "Поисковый спрос преимущественно информационный («онлайн», «скачать», «бесплатно»); коммерческих 16 запросов за 30 дней", "Платёжеспособность подтверждена только у специалистов; студентов целесообразно вести на Free; цену проверить опросом"],
             ["Трафик конкурентов высокий, поисковый спрос низкий — проверить рекламу, соцсети, приложения, прямой трафик", f"Трафик выборки 9,0 млн визитов в месяц, трафик рынка по РБ около {n(cell_sw_market(), 0)} визитов; Вордстат — сотни запросов", "Аудитория приходит не только через Яндекс: у plantuml.com Organic 48,5 %, остальное — прямой трафик и рефералы; Google и расширения редакторов кода (миллионы установок) поисковым спросом Яндекса не отражены"],
             ["Воронка даёт малый объём при большом рынке — проблема в канале, а не в ёмкости", f"Воронка поискового канала {n(cv['rev_year'][1], 1)} BYN/год при SAM {n(S['MARKET']['ПК-X (SAM)'][1], 0)} BYN", "Подтверждается: измерен единственный канал (органический поиск); каналы, требующие рекламных кабинетов, не измерены (🔲 ДОСНЯТЬ: табл. {T:todo}, п. 5)"],
             ["Сценарии сильно различаются — собрать данные по конверсиям, ценам, конкурентам, сегментам", f"Отношение оптимистичного к осторожному: ПК-X {n(S['MARKET']['ПК-X (SAM)'][2] / S['MARKET']['ПК-X (SAM)'][0], 1)}×, SW-X {n(S['MARKET']['SW-X (рынок)'][2] / S['MARKET']['SW-X (рынок)'][0], 1)}×", "Разброс значителен; приоритетные данные — конверсия Free → Pro, доля платящих, срок удержания, доли стран по Similarweb"],
             ["Итог — диапазон, а не одно число", "Результат приведён диапазоном с указанием уровня и ограничений", "Выполнено"]],
            note=f"Клиентские методы и методы по трафику Similarweb различаются примерно в {n(ratio_cl_sw, 0)} раз (базовые сценарии). Причины: доля Беларуси в визитах (допущение Д-01) и выборка из четырёх доменов занижают трафиковую оценку; ПК-X, напротив, опирается на численность групп и допущенные коэффициенты, не проверенные опросом. Согласовать порядок величины можно только дополнительными данными, поэтому итоговый диапазон приводится шире, чем у отдельных методов.")
    # ---- сопоставление основного чека 40 USD с альтернативным 48 USD (значения прежнего расчёта)
    AS_, AP_ = ALT["summary"], ALT["pl"]["seg"]
    rows = [["Годовой чек Pro, BYN", n(R["cheques"][1], 2), n(ALT["cheques"][1], 2), n(ALT["cheques"][1] / R["cheques"][1], 2)],
            ["Месячный эквивалент, BYN", n(I.PRICE_BYN_MONTH, 2), n(I.PRICE_BYN_MONTH_ALT, 2), n(I.PRICE_BYN_MONTH_ALT / I.PRICE_BYN_MONTH, 2)],
            ["Доля месячной стипендии студента, %", n(pl["seg"][0]["share_income"] * 100, 2), n(AP_[0]["share_income"] * 100, 2), n(AP_[0]["share_income"] / pl["seg"][0]["share_income"], 2)],
            ["Доля месячной зарплаты специалиста, %", n(pl["seg"][1]["share_income"] * 100, 3), n(AP_[1]["share_income"] * 100, 3), n(AP_[1]["share_income"] / pl["seg"][1]["share_income"], 2)],
            ["Индекс платёжеспособности (бюджет / цена): студенты / специалисты / преподаватели",
             " / ".join(n(x["index"], 2) for x in pl["seg"]), " / ".join(n(x["index"], 2) for x in AP_), n(AP_[1]["index"] / pl["seg"][1]["index"], 2)],
            ["Коэффициент оправданности: специалисты / преподаватели", " / ".join(n(pl["seg"][i]["justif"], 2) for i in (1, 2)), " / ".join(n(AP_[i]["justif"], 2) for i in (1, 2)), n(AP_[1]["justif"] / pl["seg"][1]["justif"], 2)]]
    for grp, lab in (("MARKET", "рынок (SAM)"), ("SOM", "SOM")):
        for k, v in S[grp].items():
            rows.append([f"{k}, {lab}, базовый сценарий, BYN/год", n(v[1], 0), n(AS_[grp][k][1], 0), n(AS_[grp][k][1] / v[1], 2)])
    d.table("alt48", "Сопоставление основного чека 40 USD в год с альтернативным 48 USD в год (4 USD × 12)",
            ["Показатель", "40 USD в год (основной)", "48 USD в год (альтернативный)", "Отношение 48 / 40"], rows,
            note="В третьем столбце — значения прежнего расчёта (чек Pro 145,37 BYN); пересчёт выполнен по тем же формулам и допущениям, меняется только цена Pro. Объёмы рынка и достижимая выручка прямо пропорциональны годовому чеку (отношение 1,2); доли цены в доходе растут, индекс платёжеспособности и коэффициент оправданности падают в той же пропорции. Медиана входных тарифов конкурентов в оптимистичном сценарии от цены Pro не зависит. Вывод о бесплатном тарифе для студентов от выбора чека не меняется.")
    d.h(4, "2.10.4 Итоговый вывод")
